function caesar(text, shift) {
    let result = "";
    for (const ch of text) {
        const code = ch.charCodeAt(0);
        if (code >= 97 && code <= 122) {
            result += String.fromCharCode(((code - 97 + shift + 26) % 26) + 97);
        } else {
            result += ch;
        }
    }
    return result;
}
const secret = caesar("salom dunyo", 3);
