function wrap(text, width) {
    const lines = [];
    let line = "";
    for (const word of text.split(" ")) {
        if ((line + " " + word).trim().length > width) {
            lines.push(line);
            line = word;
        } else {
            line = (line + " " + word).trim();
        }
    }
    if (line) lines.push(line);
    return lines;
}
