const table = {
    "а": "a", "б": "b", "д": "d", "е": "e", "и": "i", "к": "k", "қ": "q", "л": "l",
    "м": "m", "н": "n", "о": "o", "р": "r", "с": "s", "т": "t", "у": "u", "х": "x", "ш": "sh",
};
function toLatin(text) {
    let result = "";
    for (const ch of text) {
        const lower = ch.toLowerCase();
        const latin = table[lower];
        if (latin === undefined) result += ch;
        else result += ch === lower ? latin : latin[0].toUpperCase() + latin.slice(1);
    }
    return result;
}
