function tokenize(src) {
    const token = /\s*(?:(?<num>\d+(?:\.\d+)?)|(?<op>[-+*/()]))/y;
    const tokens = [];
    while (token.lastIndex < src.length) {
        const pos = token.lastIndex;
        const m = token.exec(src);
        if (!m) throw new Error(`Noma'lum qism: ${JSON.stringify(src.slice(pos).trim())}`);
        tokens.push(m.groups.num ?? m.groups.op);
    }
    return tokens;
}

