function ways(n) {
    if (n === 0) return 1;
    let total = 0;
    for (let first = 1; first <= n; first++) {
        total += ways(n - first);
    }
    return total;
}

for (const n of [1, 5, 10, 15, 20]) {
    console.log(n, ways(n));
}

