function parseDate(text) {
    const m = /^(?<y>\d{4})-(?<m>\d{2})-(?<d>\d{2})$/.exec(text);
    if (!m) return "shakl noto'g'ri";
    const { y, m: month, d } = m.groups;
    const date = new Date(Date.UTC(Number(y), Number(month) - 1, Number(d)));
    const real = date.getUTCMonth() === Number(month) - 1 && date.getUTCDate() === Number(d);
    return real ? date.toISOString().slice(0, 10) : "bunday sana yo'q";
}

